import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class CF552C {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int w = in.nextInt();
		int m = in.nextInt();
		in.close();

		int[] basew = new int[100];

		int counter = 0;

		while (m > 0) {
			int rem = m % w;
			basew[counter] = rem;
			m = m / w;
			counter++;
		}

		//System.out.println(Arrays.toString(basew));

		for (int i = 0; i < basew.length; i++) {
			if(basew[i] == 1 || basew[i] == 0 || basew[i] == -1) {
				continue;
			} else if(basew[i] == w - 1) {
				basew[i] -= w;
				basew[i + 1] = (basew[i + 1] + 1);
			} else if(basew[i] == w){
				basew[i] = 0;
				basew[i+1] = basew[i+1]+1;
			} else {
				System.out.println("NO");
				System.exit(0);
			}
		}
		//System.out.println(Arrays.toString(basew));
		System.out.println("YES");
	}
}

